<template>
  <div class="dashboard"><AdminNav /><main>
    <header class="page-header"><div><span class="eyebrow"><i class="fa-solid fa-wave-square"></i> Centro de control</span><h1>Todo bajo<br><em>control.</em></h1><p>Una lectura rápida de las conversaciones y órdenes que llegaron a Megaprinter.</p></div><button class="refresh" @click="load"><i class="fa-solid fa-rotate"></i> Actualizar</button></header>
    <section class="metrics"><article><div class="metric-icon blue"><i class="fa-solid fa-inbox"></i></div><div><span>Total de solicitudes</span><strong>{{ orders.length }}</strong><small>Últimos registros</small></div></article><article><div class="metric-icon green"><i class="fa-brands fa-whatsapp"></i></div><div><span>Contacto por WhatsApp</span><strong>{{ whatsappOrders }}</strong><small>Esperando al equipo</small></div></article><article><div class="metric-icon purple"><i class="fa-solid fa-credit-card"></i></div><div><span>Pagos confirmados</span><strong>{{ paidOrders }}</strong><small>Payphone aprobado</small></div></article></section>
    <section class="activity"><header><div><span class="eyebrow"><i class="fa-solid fa-clock-rotate-left"></i> Actividad</span><h2>Lo más reciente</h2></div><router-link to="/admin/orders">Ver todos <i class="fa-solid fa-arrow-right"></i></router-link></header><div v-if="orders.length" class="timeline"><article v-for="order in orders.slice(0,6)" :key="order._id"><div class="source-icon" :class="order.source"><i :class="order.source === 'whatsapp' ? 'fa-brands fa-whatsapp' : 'fa-solid fa-credit-card'"></i></div><div class="entry-copy"><strong>{{ order.customerName }}</strong><span>{{ order.source === 'whatsapp' ? 'Solicitó contacto por WhatsApp' : 'Inició un pago con Payphone' }}</span><small>{{ new Date(order.createdAt).toLocaleString('es-EC') }}</small></div><div class="entry-amount"><strong>${{ order.totalAmount.toFixed(2) }}</strong><span :class="order.status">{{ statusLabel(order.status) }}</span></div></article></div><div v-else class="empty"><i class="fa-solid fa-chart-simple"></i><h3>Sin actividad por ahora</h3><p>Las nuevas solicitudes aparecerán aquí automáticamente.</p></div></section>
  </main></div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import axios from 'axios'
import AdminNav from '@/components/AdminNav.vue'
import { apiBase } from '@/services/api'
interface Order { _id:string; customerName:string; totalAmount:number; source:'payphone'|'whatsapp'; status:string; createdAt:string }
const orders=ref<Order[]>([]); const token=sessionStorage.getItem('admin-token')||''
const whatsappOrders=computed(()=>orders.value.filter(order=>order.source==='whatsapp').length); const paidOrders=computed(()=>orders.value.filter(order=>order.status==='paid').length)
const load=async()=>{orders.value=(await axios.get(`${apiBase}/orders`,{headers:{Authorization:`Bearer ${token}`}})).data}; const statusLabel=(status:string)=>({paid:'Pagado',pending:'Pendiente',cancelled:'Cancelado',whatsapp:'WhatsApp'}[status]||status); onMounted(load)
</script>

